// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }

    function testFuzz_property(address from, uint256 v, uint256 tosLen) public {
        tosLen = bound(tosLen, 1, 5);
        address[] memory tos = new address[](tosLen);
        for (uint256 i = 0; i < tosLen; i++) {
            tos[i] = address(uint160(uint256(keccak256(abi.encode(i, tosLen)))));
        }

        Recorder rec = new Recorder();
        bool ok = true;
        try c.transfer(from, address(rec), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference: exactly tosLen calls. Bug: tosLen+1 calls (one extra bogus call
        // with an out-of-bounds index decoding to address(0)).
        assertTrue(ok && rec.callCount() == tosLen);
    }
}

contract Recorder {
    uint256 public callCount;
    bytes4 public constant SEL = bytes4(keccak256("transferFrom(address,address,uint256)"));

    fallback() external payable {
        callCount++;
    }

    receive() external payable {
        callCount++;
    }
}
